using System;using System.IO;using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class PerformanceDensitySmoke {
 const string Root="Docs/Measurements/2026-10-03-performance/";
 public static string Start(){if(!Application.isPlaying||!(Environment.GetEnvironmentVariable("ETERNAL_STEAM_SAVE_TEST_ROOT")??"").Contains("performance"))throw new Exception("Isolated Play required");var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();if(s.Enemies.Alive!=0)throw new Exception("Empty fresh fixture required");var destination=s.Content.MainBase!=null?s.Content.MainBase.Position:Vector3.zero;var origin=destination+Vector3.forward*40;for(int i=0;i<1000;i++){var p=origin+new Vector3((i%32)*.4f,0,(i/32)*.4f);if(!s.Enemies.TrySpawn(p,destination,1,100,false))throw new Exception("Spawn rejected");}s.Clock.Paused=false;s.Running=true;new GameObject("Density auto cleanup").AddComponent<DensityAutoCleanup>();return "1000 ground enemies in actual simulation and renderer";}
 public static string Finish(){var s=UnityEngine.Object.FindFirstObjectByType<OpenWorldSandbox>();var result=new JObject{{"scene",UnityEngine.SceneManagement.SceneManager.GetActiveScene().path},{"campaignAvailable",s.Persistence!=null},{"alive",s.Enemies.Alive},{"defeated",s.Content.Defeated},{"pendingSimulationSeconds",s.PendingSimulationTime},{"result",s.Enemies.Alive==1000&&!s.Content.Defeated?"PASS":"FAIL"},{"researchExperiment",false}};s.Enemies.DespawnAll();s.EnemyAttacks.Reset();s.TargetAdapter.Reset();File.WriteAllText(Root+"density-smoke.json",result.ToString());return result.ToString();}
}

public sealed class DensityAutoCleanup:MonoBehaviour{System.Collections.IEnumerator Start(){while(!File.Exists("Docs/Measurements/2026-10-03-performance/after-density-1000.json"))yield return null;PerformanceDensitySmoke.Finish();Destroy(gameObject);}}
